<body>
    <!-- 患者档案标题 -->
    <div class="patient-title">
        <h1>🏥 患者档案</h1>
        <div class="subtitle">巨根症候群治疗记录与监测系统</div>
    </div>

    <div class="medical-chart" id="medical-chart">
        <div class="chart-section">
            <div class="section-header" onclick="toggleSection(this)">
                <span><span class="medical-icon">🌍</span>环境监测</span>
                <span class="toggle-arrow">▼</span>
            </div>
            <div class="section-content">
                <div class="medical-grid" id="world-status"></div>
            </div>
        </div>

        <div class="chart-section">
            <div class="section-header" onclick="toggleSection(this)">
                <span><span class="medical-icon">🩺</span>生理指标</span>
                <span class="toggle-arrow">▼</span>
            </div>
            <div class="section-content">
                <div class="medical-grid" id="physiology-status"></div>
            </div>
        </div>

        <div class="chart-section collapsed">
            <div class="section-header" onclick="toggleSection(this)">
                <span id="pregnancy-title"><span class="medical-icon">🤰</span>妊娠档案</span>
                <span class="toggle-arrow">▼</span>
            </div>
            <div class="section-content">
                <div class="patient-records" id="pregnancy-records"></div>
            </div>
        </div>

        <div class="chart-section collapsed">
            <div class="section-header" onclick="toggleSection(this)">
                <span id="offspring-title"><span class="medical-icon">👶</span>后代档案</span>
                <span class="toggle-arrow">▼</span>
            </div>
            <div class="section-content">
                <div class="patient-records" id="offspring-records"></div>
            </div>
        </div>

        <div class="chart-section collapsed">
            <div class="section-header" onclick="toggleSection(this)">
                <span><span class="medical-icon">💕</span>医患关系</span>
                <span class="toggle-arrow">▼</span>
            </div>
            <div class="section-content">
                <div class="relationship-network" id="relationship-network"></div>
            </div>
        </div>

        <div class="chart-section">
            <div class="section-header" onclick="toggleSection(this)">
                <span><span class="medical-icon">👩‍⚕️</span>当前医生</span>
                <span class="toggle-arrow">▼</span>
            </div>
            <div class="section-content">
                <div class="patient-profile" id="current-patient"></div>
            </div>
        </div>
    </div>

    <script>
        function toggleSection(header) {
            const section = header.parentElement;
            section.classList.toggle('collapsed');
        }

        function getAffectionLevel(value) {
            if (value >= 70) return 'passionate';
            if (value >= 40) return 'warm';
            if (value >= 0) return 'neutral';
            if (value >= -30) return 'cold';
            return 'hostile';
        }

        function getArrayValue(data, defaultValue = '-') {
            if (!data) return defaultValue;
            if (Array.isArray(data)) {
                return data.length > 0 ? data[0] : defaultValue;
            }
            return String(data);
        }

        // 新增：处理对象数据结构的函数
        function convertObjectToArray(obj) {
            if (!obj || typeof obj !== 'object') return [];
            return Object.entries(obj).map(([key, value]) => ({
                name: key,
                ...value
            }));
        }

        function renderPregnancyRecord(item, index) {
            if (!item || !item.name || typeof item.name !== 'string') {
                return '';
            }

            const isPregnant = Boolean(item.isPregnant);
            const statusClass = isPregnant ? 'pregnant' : 'not-pregnant';
            const statusText = isPregnant ? '已怀孕' : '未怀孕';
            const injectionCount = Number(item.injectionCount) || 0;
            const pregnancyCycle = Number(item.pregnancyCycle) || 0;
            const pregnancyCount = Number(item.pregnancyCount) || 0;
            const developmentAcceleration = Number(item.developmentAcceleration) || 0;
            const acceleratedDays = Number(item.acceleratedPregnancyDays) || 280;
            const naturalDays = Number(item.naturalPregnancyDays) || 280;
            const lastAcceleration = item.lastAccelerationDate || '';
            const accelerationSource = item.accelerationSource || '';

            let accelerationInfo = '';
            if (developmentAcceleration > 0 && isPregnant) {
                const savedDays = naturalDays - acceleratedDays;
                accelerationInfo = `
                    <div class="acceleration-info">
                        🚀 发育加速: ${developmentAcceleration}天 |
                        预计缩短: ${savedDays}天 |
                        最近加速: ${lastAcceleration} |
                        加速原因: ${accelerationSource}
                    </div>
                `;
            }

            return `
                <div class="record-card">
                    <div class="record-header">
                        <div class="record-number">${index + 1}</div>
                        <div class="record-title">${item.name}</div>
                        <div class="record-status status-${statusClass}">${statusText}</div>
                    </div>
                    <div class="record-details">
                        <div class="detail-item">
                            <div class="detail-label">内射次数</div>
                            <div class="detail-value">${injectionCount} 次</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">孕育周期</div>
                            <div class="detail-value">${pregnancyCycle} 周</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">历史孕育</div>
                            <div class="detail-value">${pregnancyCount} 次</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">预计孕期</div>
                            <div class="detail-value">${acceleratedDays} 天</div>
                        </div>
                    </div>
                    ${accelerationInfo}
                </div>
            `;
        }

        function renderOffspringRecord(item, index) {
            if (!item || !item.name || typeof item.name !== 'string') {
                return '';
            }

            const gender = item.gender || '未知';
            const age = item.age !== undefined ? Number(item.age) : 0;
            const mother = item.mother || '未知';
            const name = item.name || '未命名';
            const birthDate = item.birthDate || '未知';
            const specialTraits = item.specialTraits || '无特殊特征';

            return `
                <div class="record-card">
                    <div class="record-header">
                        <div class="record-number">${index + 1}</div>
                        <div class="record-title">${name}</div>
                        <div class="record-status status-born">已出生</div>
                    </div>
                    <div class="record-details">
                        <div class="detail-item">
                            <div class="detail-label">性别</div>
                            <div class="detail-value">${gender}</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">年龄</div>
                            <div class="detail-value">${age} 岁</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">母亲</div>
                            <div class="detail-value">${mother}</div>
                        </div>
                        <div class="detail-item">
                            <div class="detail-label">出生日期</div>
                            <div class="detail-value">${birthDate}</div>
                        </div>
                    </div>
                    <div class="trait-tag">${specialTraits}</div>
                </div>
            `;
        }

        function renderRecordSection(containerId, data, titleId, recordType) {
            const container = document.getElementById(containerId);
            const title = document.getElementById(titleId);

            // 检查数据是否存在
            if (!data) {
                container.innerHTML = `
                    <div class="empty-records">
                        <span class="empty-icon">${recordType === 'pregnancy' ? '🤰' : '👶'}</span>
                        <div>暂无相关档案记录</div>
                    </div>
                `;
                if (title) {
                    const iconMap = { pregnancy: '🤰', offspring: '👶' };
                    title.innerHTML = `<span class="medical-icon">${iconMap[recordType]}</span>${recordType === 'pregnancy' ? '妊娠档案' : '后代档案'}<span class="count-display">0 例</span>`;
                }
                return;
            }

            // 获取实际数据
            let actualData;
            if (Array.isArray(data)) {
                // 如果是数组，取第一个元素（应该是对象）
                actualData = data.length > 0 ? data[0] : {};
            } else {
                // 如果直接是对象，直接使用
                actualData = data;
            }

            // 将对象转换为数组格式
            const itemsArray = convertObjectToArray(actualData);
            const validItems = itemsArray.filter(item => item && item.name && typeof item.name === 'string' && item.name.trim() !== '');
            const count = validItems.length;

            // 更新标题
            if (title) {
                const iconMap = { pregnancy: '🤰', offspring: '👶' };
                title.innerHTML = `<span class="medical-icon">${iconMap[recordType]}</span>${recordType === 'pregnancy' ? '妊娠档案' : '后代档案'}<span class="count-display">${count} 例</span>`;
            }

            // 如果没有有效数据，显示空记录
            if (count === 0) {
                container.innerHTML = `
                    <div class="empty-records">
                        <span class="empty-icon">${recordType === 'pregnancy' ? '🤰' : '👶'}</span>
                        <div>暂无相关档案记录</div>
                    </div>
                `;
                return;
            }

            // 渲染记录
            if (recordType === 'pregnancy') {
                container.innerHTML = validItems.map((item, index) => renderPregnancyRecord(item, index)).join('');
            } else if (recordType === 'offspring') {
                container.innerHTML = validItems.map((item, index) => renderOffspringRecord(item, index)).join('');
            }
        }

        async function initMedicalChart() {
            try {
                const messages = await getChatMessages(getLastMessageId());
                if (!messages || !messages[0] || !messages[0].data) {
                    throw new Error('无法获取患者数据');
                }

                const statData = messages[0].data.stat_data;
                if (!statData) {
                    throw new Error('患者档案数据缺失');
                }

                // 渲染环境监测
                const worldStatus = document.getElementById('world-status');
                if (statData.世界) {
                    const worldItems = [
                        { icon: '📅', label: '日期', key: '日期' },
                        { icon: '⏰', label: '时间', key: '时间' },
                        { icon: '📍', label: '地点', key: '地点' },
                        { icon: '🌤️', label: '天气', key: '天气' }
                    ];

                    worldStatus.innerHTML = worldItems.map(({ icon, label, key }) => {
                        const value = getArrayValue(statData.世界[key]);
                        return `
                            <div class="medical-item">
                                <span class="medical-label">${icon} ${label}</span>
                                <span class="medical-value">${value}</span>
                            </div>
                        `;
                    }).join('');
                }

                // 渲染生理指标
                const physiologyStatus = document.getElementById('physiology-status');
